{"HelperA.dfy": "O1.Certify(m, n);
    O1.Certify(K.Restrict(m, keep), K.Restrict(n, keep));
    O2.MergeKeys(m, n);
    O2.RestrictKeys(m, keep);
    O2.RestrictKeys(n, keep);
    O2.RestrictKeys(K.Merge(m, n), keep);
    O2.MergeKeys(K.Restrict(m, keep), K.Restrict(n, keep));
    assert K.Restrict(K.Merge(m, n), keep).Keys == K.Merge(K.Restrict(m, keep), K.Restrict(n, keep)).Keys;
    forall key0 | key0 in K.Restrict(K.Merge(m, n), keep)
      ensures key0 in K.Merge(K.Restrict(m, keep), K.Restrict(n, keep))
      ensures K.Restrict(K.Merge(m, n), keep)[key0] == K.Merge(K.Restrict(m, keep), K.Restrict(n, keep))[key0]
    {
      O2.RestrictAt(K.Merge(m, n), keep, key0);
      O2.MergeAt(m, n, key0);
      if key0 in m {
        O2.RestrictAt(m, keep, key0);
        O2.MergeAt(K.Restrict(m, keep), K.Restrict(n, keep), key0);
      } else {
        O2.RestrictAt(n, keep, key0);
        O2.MergeAt(K.Restrict(m, keep), K.Restrict(n, keep), key0);
      }
    }
    A.Equal(K.Restrict(K.Merge(m, n), keep), K.Merge(K.Restrict(m, keep), K.Restrict(n, keep)));"}

